<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a2f;
      --panel-strong: #17213a;
      --text: #edf2ff;
      --muted: #9ba8c7;
      --accent: #7c5cff;
      --accent-strong: #9f8cff;
      --border: #26324f;
      --success: #31d0aa;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(124, 92, 255, 0.26), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(49, 208, 170, 0.18), transparent 28rem),
        var(--bg);
      display: grid;
      place-items: center;
      padding: 2rem;
    }

    main {
      width: min(100%, 780px);
    }

    .quiz-card {
      background: rgba(18, 26, 47, 0.86);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 28px;
      box-shadow: 0 28px 80px rgba(0, 0, 0, 0.38);
      backdrop-filter: blur(18px);
      padding: clamp(1.25rem, 4vw, 2.5rem);
    }

    .eyebrow {
      color: var(--success);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.16em;
      margin: 0 0 0.6rem;
      text-transform: uppercase;
    }

    h1 {
      font-size: clamp(2rem, 5vw, 3.4rem);
      line-height: 1;
      margin: 0;
    }

    .intro {
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.6;
      margin: 1rem 0 2rem;
      max-width: 58ch;
    }

    form {
      display: grid;
      gap: 1.15rem;
    }

    .form-field {
      background: linear-gradient(180deg, rgba(23, 33, 58, 0.96), rgba(18, 26, 47, 0.96));
      border: 1px solid var(--border);
      border-radius: 22px;
      padding: 1.25rem;
    }

    .question-title {
      display: block;
      font-size: 1.15rem;
      font-weight: 750;
      margin-bottom: 0.4rem;
    }

    .help-text {
      color: var(--muted);
      font-size: 0.95rem;
      line-height: 1.5;
      margin: 0 0 1rem;
    }

    .choices {
      display: grid;
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .choice {
      align-items: center;
      background: rgba(11, 16, 32, 0.62);
      border: 1px solid rgba(155, 168, 199, 0.22);
      border-radius: 16px;
      cursor: pointer;
      display: flex;
      gap: 0.8rem;
      padding: 0.85rem 1rem;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      background: rgba(124, 92, 255, 0.12);
      border-color: rgba(159, 140, 255, 0.58);
      transform: translateY(-1px);
    }

    input[type="checkbox"] {
      width: 1.1rem;
      height: 1.1rem;
      margin: 0;
      accent-color: var(--accent);
    }

    .choice span {
      color: #dfe6fb;
      font-weight: 600;
    }

    .actions {
      align-items: center;
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      justify-content: space-between;
      margin-top: 0.5rem;
    }

    button {
      background: linear-gradient(135deg, var(--accent), #4fd1c5);
      border: 0;
      border-radius: 999px;
      color: #ffffff;
      cursor: pointer;
      font: inherit;
      font-weight: 800;
      letter-spacing: 0.02em;
      padding: 0.95rem 1.45rem;
      box-shadow: 0 14px 30px rgba(124, 92, 255, 0.3);
      transition: filter 160ms ease, transform 160ms ease;
    }

    button:hover {
      filter: brightness(1.08);
      transform: translateY(-1px);
    }

    #result {
      color: var(--muted);
      font-weight: 700;
      margin: 0;
      min-height: 1.5rem;
    }
  </style>
</head>
<body>
  <main>
    <section class="quiz-card" aria-labelledby="quiz-title">
      <p class="eyebrow">Multiple answer quiz</p>
      <h1 id="quiz-title">Computer Languages</h1>
      <p class="intro">Choose every answer that fits each question, then submit to see how many selections you made.</p>

      <form id="language-quiz">
        <div class="form-field">
          <span class="question-title" id="question-1">1. Which of these are programming languages?</span>
          <p class="help-text">Select all options that are commonly used to write executable software.</p>
          <div class="choices" role="group" aria-labelledby="question-1">
            <label class="choice">
              <input type="checkbox" name="programming-languages" value="Python">
              <span>Python</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="programming-languages" value="HTML">
              <span>HTML</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="programming-languages" value="JavaScript">
              <span>JavaScript</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="programming-languages" value="CSS">
              <span>CSS</span>
            </label>
          </div>
        </div>

        <div class="form-field">
          <span class="question-title" id="question-2">2. Which languages are often used for web development?</span>
          <div class="choices" role="group" aria-labelledby="question-2">
            <label class="choice">
              <input type="checkbox" name="web-languages" value="JavaScript">
              <span>JavaScript</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="web-languages" value="TypeScript">
              <span>TypeScript</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="web-languages" value="SQL">
              <span>SQL</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="web-languages" value="PHP">
              <span>PHP</span>
            </label>
          </div>
        </div>

        <div class="form-field">
          <span class="question-title" id="question-3">3. Which languages are known for systems programming?</span>
          <div class="choices" role="group" aria-labelledby="question-3">
            <label class="choice">
              <input type="checkbox" name="systems-languages" value="C">
              <span>C</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="systems-languages" value="Rust">
              <span>Rust</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="systems-languages" value="Ruby">
              <span>Ruby</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="systems-languages" value="Zig">
              <span>Zig</span>
            </label>
          </div>
        </div>

        <div class="actions">
          <button type="submit">Submit answers</button>
          <p id="result" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const quiz = document.querySelector("#language-quiz");
    const result = document.querySelector("#result");

    quiz.addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedCount = quiz.querySelectorAll("input[type='checkbox']:checked").length;
      result.textContent = selectedCount === 1
        ? "You selected 1 answer."
        : `You selected ${selectedCount} answers.`;
    });
  </script>
</body>
</html>
